def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core, _ = core.split('+', 1)
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def pre_key(pre_ids):
        if pre_ids is None:
            return None
        key = []
        for ident in pre_ids:
            if ident.isdigit():
                key.append((0, int(ident), ''))
            else:
                key.append((1, 0, ident))
        return key

    def cmp(a, b):
        amaj, amin, apat, apre = a
        bmaj, bmin, bpat, bpre = b
        if amaj != bmaj:
            return -1 if amaj < bmaj else 1
        if amin != bmin:
            return -1 if amin < bmin else 1
        if apat != bpat:
            return -1 if apat < bpat else 1
        if apre is None and bpre is None:
            return 0
        if apre is None:
            return 1
        if bpre is None:
            return -1
        ak = pre_key(apre)
        bk = pre_key(bpre)
        for x, y in zip(ak, bk):
            if x != y:
                return -1 if x < y else 1
        if len(ak) != len(bk):
            return -1 if len(ak) < len(bk) else 1
        return 0

    import functools
    parsed = [(parse(v), i, v) for i, v in enumerate(versions)]

    def full_cmp(a, b):
        c = cmp(a[0], b[0])
        if c != 0:
            return c
        return a[1] - b[1]

    parsed.sort(key=functools.cmp_to_key(full_cmp))
    return [p[2] for p in parsed]

